previewCss:
.darma-loader-darma-b17-jenga-tower { --accent: var(--loader-color, #d97706); --accent-2: var(--loader-secondary-color, #fef3c7); width: var(--loader-size, 112px); height: var(--loader-size, 112px); position: relative; }
.darma-loader-darma-b17-jenga-tower span { position: absolute; left: 24%; width: 52%; height: 15%; border-radius: 3px; background: linear-gradient(color-mix(in srgb, #fff 22%, var(--accent)), var(--accent)); box-shadow: inset 0 0 0 1px color-mix(in srgb, #000 18%, transparent); animation: darma-loader-darma-b17-jenga-tower-jenga-settle calc(var(--loader-speed, 1s) * 3) ease-in-out infinite; }
.darma-loader-darma-b17-jenga-tower span:nth-of-type(1) { bottom: 4%; }
.darma-loader-darma-b17-jenga-tower span:nth-of-type(2) { bottom: 22%; }
.darma-loader-darma-b17-jenga-tower span:nth-of-type(3) { bottom: 40%; }
.darma-loader-darma-b17-jenga-tower span:nth-of-type(4) { bottom: 58%; }
.darma-loader-darma-b17-jenga-tower span:nth-of-type(5) { bottom: 76%; }
.darma-loader-darma-b17-jenga-tower .darma-loader-darma-b17-jenga-tower__pull { position: absolute; left: 24%; bottom: 40%; width: 52%; height: 15%; border-radius: 3px; background: linear-gradient(color-mix(in srgb, #fff 30%, var(--accent-2)), var(--accent-2)); box-shadow: 0 3px 8px color-mix(in srgb, #000 30%, transparent); animation: darma-loader-darma-b17-jenga-tower-jenga-move calc(var(--loader-speed, 1s) * 3) cubic-bezier(.5, 0, .3, 1) infinite; }
@keyframes darma-loader-darma-b17-jenga-tower-jenga-move { 0%, 8% { transform: translate(0, 0); } 30% { transform: translate(44%, 0); } 56% { transform: translate(44%, -300%); } 80%, 100% { transform: translate(0, -300%); } }
@keyframes darma-loader-darma-b17-jenga-tower-jenga-settle { 0%, 52% { transform: translateY(0) rotate(0deg); } 62% { transform: translateY(2%) rotate(-.8deg); } 76%, 100% { transform: translateY(0) rotate(0deg); } }

